"""Serialize the authored professional award design, not a licensing engine."""
import json
import re
from pathlib import Path
RUN = Path(__file__).resolve().parent

def refs(*ns): return [f'SRC-{n:03d}' for n in ns]

def build():
    rows = [
      ('Verifiable Credentials Data Model v2.0','W3C','https://www.w3.org/TR/vc-data-model-2.0/','2.0; dated pin and errata audit pending','standard','Selected verification, holder/subject and trust distinctions; not full VC conformance.'),
      ('Bitstring Status List v1.0','W3C','https://www.w3.org/TR/vc-bitstring-status-list/','1.0; dated pin pending','standard','Selected purpose and refresh semantics; no implemented status-list adapter.'),
      ('Practitioner','HL7','https://hl7.org/fhir/R5/practitioner.html','R5 5.0.0','standard','Selected qualification fields and separation from organization-specific authorization.'),
      ('The licence to practise','General Medical Council','https://www.gmc-uk.org/registration-and-licensing/our-registers/a-guide-to-our-registers/the-licence-to-practise','Guidance inspected 2026-09-09','public-authority','UK example of registration, licence and revalidation; not a universal legal rule.'),
      ('What is a regulated profession','European Union Your Europe','https://europa.eu/youreurope/citizens/work/professional-qualifications/regulated-professions/index_en.htm','Guidance inspected 2026-09-09','public-authority','Selected jurisdiction and recognition distinctions; no individual eligibility determination.'),
      ('Credential Engine Schemas Handbook','Credential Engine','https://www.credreg.net/ctdl/handbook','Header 2024-02-20; schema release pin pending','first-party-doc','Selected scheme graph, job-license, maintenance and revocation-profile passages. Direct License term page unavailable.')]
    sources = [dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type=k,primary_source=True,authority_tier=1,accessed_at='2026-09-09T23:01:00Z',relevance=r) for i,(t,o,u,v,k,r) in enumerate(rows,1)]
    ids=['award-binding','award-scheme','award-basis','award-practice-scope','award-validity','award-renewal','award-status-change','award-remedy','award-verification','award-disclosure','award-recognition','award-projection']
    citations=[refs(1,3),refs(3,4,6),refs(3,5,6),refs(3,4,5),refs(1,2,3),refs(4,6),refs(2,3,6),refs(1,5,6),refs(1,2,4),refs(1),refs(5,6),refs(1,2,3,6)]
    kinds=[['identity','relationship','quality'],['classification','authority','classification'],['requirement','evidence','temporal'],['spatial','constraint','authority'],['temporal','state','quality'],['requirement','evidence','lifecycle'],['event','temporal','exception'],['process','decision','retention'],['provenance','validation','constraint'],['access','privacy','retention'],['spatial','decision','interoperability'],['interoperability','constraint','validation']]
    bundles=[]; n=0
    for group in re.split(r'(?m)^## ',(RUN/'question-design.md').read_text(encoding='utf-8'))[1:]:
        title=re.sub(r'^\d+\s+','',group.split('\n',1)[0]); layers=[]
        for section in re.split(r'(?m)^### ',group)[1:]:
            heading,body=section.split('\n',1); name=re.sub(r'^\d+\.\d+\s+','',heading)
            qs,answers=body.split('Answer groups:',1)
            questions=re.findall(r'(?m)^\d\. (.+\?)$',qs); groups=re.findall(r'([a-zA-Z]+)\{([^}]+)\}',answers)
            assert len(questions)==len(groups)==3
            lid=ids[n]; sr=citations[n]
            desc='Authored credential-record design for '+name.lower()+'. Selected sources motivate distinctions; profile rules and operational implementation remain separate.'
            fields=[dict(id=lid+'-'+key.lower(),name=key,description='Proposed members: '+members+'. Required container may explicitly record unknown or not-applicable; nested executable schemas are deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr) for key,members in groups]
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr,questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[n][i],answer_data=[fields[i]['id']]) for i,q in enumerate(questions)],data_elements=fields,artifacts=[dict(id=lid+'-artifact',name=name+' evidence record',description='Minimal authorized evidence reference or attributed record, not a fabricated credential or public copy of private assessment material.',media_or_form=['text/markdown','application/json','application/yaml','authorized reference'],serial=True,identity_strategy='Master-qualified award ID, governed issuer URI or Dimension UUID, with separate revision and digest; not names or timestamp alone.',source_refs=sr)],inline_only_rationale=None)
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr,findings=[finding])); n+=1
        bundles.append(dict(id='credential-'+re.sub('[^a-z]+','-',title.lower()).strip('-'),name=title,description='Individual credential '+title.lower()+'.',rationale='Groups award-owned records without taking ownership of issuer schemes, people or legal authorization decisions.',source_refs=sorted(set(s for l in layers for s in l['source_refs'])),layers=layers))
    assert n==12 and len(bundles)==6
    model=dict(registry_id='vr.wm-per-013',model_id='WM-PER-013',name='Professional License / Credential',entry_kind='entity',purpose='Describe an individually awarded professional credential with evidenced scope, issuer, validity and governance.',scope_statement='One governed award record with references to its subject, scheme, issuing authority, status evidence and recognition decisions; not an automatic grant of professional practice rights.',in_scope=['Award identity, credential kind, subject binding, issuer and scheme references','Award basis, scope, continuing requirements, status and remedies','Verification observations, privacy-aware presentation and loss-aware mapping'],out_of_scope=['Issuing or revoking a real credential, professional advice or legal eligibility decisions','Mastering person identity, complete training records or regulator case files','Implementing cryptographic verification, external register access or jurisdictional rule engines'],boundary_notes=[dict(neighbor=a,distinction=b,source_refs=s) for a,b,s in [('Credential scheme','Scheme requirements and individual award have separate identities and maintenance cycles.',refs(6)),('Person and holder','Award subject and repository holder may differ; identity masters remain references.',refs(1,3)),('Practice authorization','Qualification and valid document do not alone authorize the intended role or location.',refs(3,4,5)),('Verifiable credential envelope','Proof validity and claim truth are distinct; envelope ID is not necessarily award ID.',refs(1)),('Attestation / Credential','Registry parent is a general conceptual alignment, not verified structural inheritance.',refs(1,3))]])
    services=dict(
      dimension=dict(owner_package_requirements=['Declare award-record owner and authorized steward.','Identify subject, scheme, issuer and status evidence masters.','Bind disclosure, freshness, correction, retention and reliance policies.'],namespace_guidance='Use issuer-qualified award IDs; keep subject, scheme, envelope and local revision IDs distinct. Do not expose private identity in public paths.',registry_links=['Award registry','Person and organization references','Scheme and jurisdiction references','Status observation and protected evidence registry']),
      canon_and_patch=dict(canonicalization_rules=['Preserve source vocabulary, award scope and authority qualifiers.','Separate effective intervals, envelope periods and observation times; unknown is not active.'],patch_rules=['Pin base version and digest; namespace profession and jurisdiction profiles.','Append corrections under expected-head checks; retain competing reports where permitted.'],compatibility_rules=['Do not merge license, certification, membership and qualification semantics.','Refuse export when required scope, status freshness or authority qualifiers would be lost.']),
      artifact_rules=dict(identity_priority=['Master-system issuer-qualified award identifier','Governed issuer-qualified URI','Dimension-issued UUID'],timestamp_rule='Use RFC 3339 seconds and explicit offset or Z for recording instants; preserve date-only and uncertain effective periods separately.',serial_naming_rule='Opaque award ID, record kind and revision; no personal names or disciplinary details in filenames.',integrity_rule='Check exact-byte digest and revision; integrity never proves issuer authority or permission to practise.'),
      policies=['No real issuance, revocation, regulator contact or personal-record lookup follows from filling this model.','Never equate good signature, active local record, qualification and current practice permission.','Treat unavailable or stale status as unknown under the relying policy, not good standing.','Collect only necessary authorized evidence and protect disciplinary or assessment details.'],
      crud=dict(read=['Read Dimension policy, pinned specification, assurance holds and permitted evidence scope before accessing award records.'],create=['Record an authorized attributed award assertion; keep unknown issuer/subject binding explicit.'],update=['Append status observations or corrections with evidence, effective time and expected-head guard; local edit cannot reverse issuer decisions.'],delete=['Apply retention, legal holds and justified deletion to local records; preserve only permitted minimal tombstones. Local deletion does not revoke an award.']),
      roles=[dict(name=a,responsibilities=[b]) for a,b in [('Dimension owner','Delegates local memory authority, not credential-issuing rights.'),('Credential steward','Maintains attributed award and scope records.'),('Contributor','Provides authorized evidence references.'),('Reviewer','Checks binding, freshness and loss limits without inventing legal authority.'),('Custodian','Enforces restricted disclosure and retention.')]],
      access=dict(default_rule='Deny absent purpose-specific authority; public-register visibility is not unlimited redistribution permission.',scopes=['bundle','layer','finding','artifact'],exceptions=['Explicit scoped time-limited exception with authorizer and rationale, never an implicit privilege from credential possession.'],audit_requirements=['Log operation, opaque award/revision and authorized outcome; do not log secrets or restricted evidence contents.']),
      agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension policy and permitted purpose','Pinned credential specification and assurance','Award identity, scope and source-qualified status','Validation, disclosure, patching and retirement rules']))
    frows=[('resolve-award','Resolve award reference',['Issuer-qualified ID','Authorized subject candidates'],['Reference or ambiguity'],['Read authority','No name-only merge'],['Read-only; no award created'],refs(1,3)),('record-award','Record award assertion',['Issuer evidence','Scope and dates','Expected head'],['Attributed revision'],['Write scope','Unknowns explicit'],['Local record only; no real credential issuance'],refs(3,6)),('record-status-observation','Record status observation',['Authorized source','Source time and purpose','Freshness policy'],['Status observation or unknown'],['Source access allowed','Purpose interpreted separately'],['No regulator mutation or inferred good standing'],refs(1,2,4)),('link-renewal-evidence','Link renewal evidence',['Scheme requirements','Authorized evidence refs'],['Qualified renewal record'],['Write scope','Scheme version pinned'],['No automatic revalidation or extension of rights'],refs(4,6)),('record-recognition','Record recognition decision',['Destination scope','Authority evidence'],['Decision reference or pending state'],['Authorized evidence','Jurisdiction explicit'],['No new practice permission conferred'],refs(5,6)),('export-credential-projection','Export minimized projection',['Disclosure scope','Pinned target profile','Loss policy'],['Projection or refusal'],['Disclosure authorized','Required qualifiers preserved'],['No public release or cryptographic guarantee implied'],refs(1,2,3))]
    functions=[dict(id=i,name=n,description='Proposed record operation: '+n.lower()+'. Runtime implementation is deferred.',inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,a,b,c,e,s in frows]
    composition=[dict(target=t,relation=r,purpose=p,required=False,source_refs=s) for t,r,p,s in [('WM-XCT-017','ALIGN','Candidate general attestation alignment, not ratified inheritance.',refs(1,3)),('WM-PER-001','REFERENCE','Subject reference, not identity mastering.',refs(1,3)),(rows[0][2],'ALIGN','Optional envelope projection with separate award identity.',refs(1)),(rows[1][2],'ALIGN','Optional purpose-aware status evidence; adapter pending.',refs(2)),(rows[2][2],'ALIGN','Selected healthcare qualification mapping, not practice authority.',refs(3)),(rows[5][2],'ALIGN','Scheme and requirements references; not a substitute for individual award.',refs(6))]]
    dims=[('identity','Award, subject, scheme and envelope distinct.'),('classification','Credential kind and profession vocabulary qualified.'),('direct properties','Scope, issuer, level and validity are explicit.'),('recognition','Evidenced identification and jurisdictional recognition are separate.'),('capabilities','Six bounded record operations, not practice privileges.'),('lifecycle','Issuance record, renewal, status change, remedy and retirement.'),('relationships','Subject, issuer, scheme and relying party referenced.'),('temporal','Effective intervals and observation time distinct.'),('provenance','Authority and evidence preserved per assertion.'),('ownership','Record stewardship does not confer regulator powers.'),('access','Purpose-limited evidence and presentation.'),('retention','Local deletion does not revoke the credential.'),('interoperability','Loss-aware optional profile projections.')]
    coverage=dict(claim='Bounded professional award memory draft, not global licensing law, cryptographic runtime or independent review.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='validation',status='gap',notes='Research structure validated; executable nested fields, legal rules and negative runtime fixtures are not implemented.'),dict(dimension='physical properties',status='not-applicable',notes='Credential is an informational award record; physical document properties belong to its carrier.')],known_omissions=['Both external providers timed out once; no independent external review.','Selected clauses only; exact dated pins, updates, source licenses and full mappings pending.','GMC UK, EU recognition and FHIR healthcare examples are not universal professional rules.','Direct CTDL License term fetch unavailable; only selected handbook content admitted.','No executable nested schemas, status-list adapter, cryptographic verification, jurisdiction engine or ratified composition.'],conflicts=[],regional_assumptions=['Jurisdiction and profession profiles require competent source verification before operational reliance.'],adversarial_checks=['A holder may not be the subject.','Valid proof does not establish truth or issuer authority.','Registration is not necessarily a license.','Qualification does not authorize every organization or location.','Stale or missing status is not good standing.','Renewal is not scheme maintenance.','Recognition similarity does not confer permission.','Local deletion or correction cannot revoke or restore a real award.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
